  state = {
    navbarOpen: false
  }

  //opposite
  handleNavbar = () => {
    this.setState({ navbarOpen: !this.state.navbarOpen })
  }

  render() {
    return (
      <>
        <NavBar
          navbarState={this.state.navbarOpen}
          handleNavbar={this.handleNavbar}
        />
        <Slideshow />
        <Info />
        <About />
        <Services />
        <References />
        <GlobalStyles />
      </>
    );
  }
}

export default App;
